// spec: .qa/e2e/specs/search-prefs.md
// seed: tests/seed.free.geo.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/free-r13.json'), colorScheme: 'dark' });

test.describe('Раунд 13: автосохранение предпочтений (#2911c1)', () => {
  test('В шапке «העדפות חיפוש» нет «שמירה» @iphone @prod-safe', async ({ page }) => {
    // 1. `/settings` → «העדפות חיפוש» (или `/prefs?from=settings`).
    await page.goto('/prefs?from=settings');

    // Заголовок «העדפות חיפוש»; блоки «מי מעניין אותי» (גברים, נשים, כולם, אחר), «גיל», «מרחק».
    await expect(page.getByText('העדפות חיפוש')).toBeVisible();
    await expect(page.getByText('מי מעניין אותי')).toBeVisible();
    for (const name of ['גברים', 'נשים', 'כולם', 'אחר']) {
      await expect(page.getByRole('radio', { name })).toBeVisible();
    }
    await expect(page.getByText('גיל', { exact: true })).toBeVisible();
    await expect(page.getByText('מרחק', { exact: true })).toBeVisible();

    // 2. Взять все кнопки экрана.
    const buttons = page.getByRole('button');

    // Кнопки «שמירה» нет, текста «שמירה» нет.
    await expect(page.getByRole('button', { name: 'שמירה' })).toHaveCount(0);
    await expect(page.getByText('שמירה')).toHaveCount(0);

    // Стрелка «назад» одна, в правой части шапки (RTL).
    await expect(buttons).toHaveCount(1);
    const back = buttons.first();
    await expect(back).toBeVisible();
    const box = (await back.boundingBox())!;
    const width = page.viewportSize()!.width;
    expect(box.x + box.width / 2, 'стрелка «назад» в правой половине шапки').toBeGreaterThan(width / 2);
    expect(box.y + box.height, 'стрелка в шапке').toBeLessThan(120);
  });
});
